import { AggregateRoot, Id } from '@Architecture/Domain';

import { InvitationCreatedEvent } from './InvitationEvents';

/** An invitation as it is stored: the link's id, the group it is to, who issued it, and when. */
export interface InvitationSnapshot {
  id: string;
  groupId: string;
  invitedBy: string;
  createdAt: string;
}

/**
 * A link to a group, generated by the domain (ADR 4): whoever holds its id may join the group, any number of times.
 * It is an aggregate of its own, not a part of the group: it is read by people who are not members, and accepting it
 * changes the group, not the invitation. It is issued once and never changes, so it has one writer and no version.
 */
export class Invitation extends AggregateRoot {
  readonly #groupId: string;
  readonly #invitedBy: string;
  readonly #createdAt: Date;

  private constructor(id: Id, groupId: string, invitedBy: string, createdAt: Date) {
    super(id);
    this.#groupId = groupId;
    this.#invitedBy = invitedBy;
    this.#createdAt = createdAt;
  }

  /**
   * A new invitation to `groupId`, issued by `invitedBy` at `at`: its id is generated here, and `InvitationCreated` is
   * recorded. The caller has checked that `invitedBy` is a member of the group.
   */
  static issue({ groupId, invitedBy, at }: { groupId: string; invitedBy: string; at: Date }): Invitation {
    const invitation = new Invitation(Id.generate(), groupId, invitedBy, at);
    invitation.record(
      InvitationCreatedEvent.set({ invitationId: invitation._id.value, groupId, invitedBy, createdAt: at }),
    );
    return invitation;
  }

  /** Rebuilds an invitation as it was stored. Records nothing, and throws on data `issue()` could not have made. */
  static fromSnapshot(snapshot: InvitationSnapshot): Invitation {
    const createdAt = new Date(snapshot.createdAt);
    if (!snapshot.id || !snapshot.groupId || !snapshot.invitedBy || Number.isNaN(createdAt.getTime())) {
      throw new Error(`The stored invitation ${snapshot.id} is corrupted`);
    }
    return new Invitation(new Id(snapshot.id), snapshot.groupId, snapshot.invitedBy, createdAt);
  }

  get groupId(): string {
    return this.#groupId;
  }

  get invitedBy(): string {
    return this.#invitedBy;
  }

  get createdAt(): Date {
    return this.#createdAt;
  }

  toSnapshot(): InvitationSnapshot {
    return {
      id: this._id.value,
      groupId: this.#groupId,
      invitedBy: this.#invitedBy,
      createdAt: this.#createdAt.toISOString(),
    };
  }
}
